const d = $json;

const pageName = d.page_name || 'Unknown page';
const pageUrl = d.page_url || '';

const html = `
<h2>Page Monitor - Daily Check</h2>

<h3>${pageName}</h3>

<p>
  <a href="${pageUrl}">${pageUrl}</a>
</p>

<p>No changes were detected on this page today.</p>

<hr>

<p style="font-size:12px;color:#666;">
Generated automatically by n8n Page Monitor.
</p>
`;

return {
  json: {
    subject: `Page Monitor - ${pageName} (No changes)`,
    html
  }
};

const page = $('Get Monitored Pages2').item.json;
const err = $json.error || $json;
const message = err.message || err.description || 'Unknown error';

function escapeHtml(s = '') {
  return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
}

const html = `
  <h2>Page Monitor - Fetch Failed</h2>
  <h3>${escapeHtml(page.name)}</h3>
  <p><a href="${escapeHtml(page.url)}">${escapeHtml(page.url)}</a></p>
  <p style="color:#c00"><strong>Error:</strong> ${escapeHtml(message)}</p>
  <p>This page could not be checked today (after automatic retries). It will be retried again on the next scheduled run.</p>
  <hr><p style="font-size:12px;color:#666">Generated automatically by n8n Page Monitor.</p>`;

return { json: { subject: `Page Monitor Error - ${page.name}`, html } };

const page = $('Get Monitored Pages2').item.json;
const html = $json.data || $json.body || $json;

let text = String(html)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return {
  json: {
    page_id: page.id,
    page_name: page.name,
    page_url: page.url,
    content_text: text
  }
};

const extracted = $('Extract & Hash1').item.json;
const hashed = $('Crypto').item.json;

// Previous snapshot
const oldHash = $json.content_hash || '';
const oldText = $json.content_text || '';

// Current page information comes from Extract & Hash1
const pageId = extracted.page_id;
const pageName = extracted.page_name;
const pageUrl = extracted.page_url;

// Current page
const newHash = hashed.content_hash;
const newText = extracted.content_text || '';

if (!pageId) {
  throw new Error('page_id is missing from Extract & Hash1.');
}

if (!newHash) {
  throw new Error('Crypto did not produce content_hash.');
}

// First snapshot = baseline
if (!oldHash || !oldText) {
  return {
    json: {
      page_id: pageId,
      page_name: pageName,
      page_url: pageUrl,

      changed: false,
      is_baseline: true,

      old_hash: '',
      new_hash: newHash,

      old_text: '',
      new_text: newText,

      added: [],
      removed: [],

      added_count: 0,
      removed_count: 0,
      changed_count: 0
    }
  };
}

// No change
if (oldHash === newHash) {
  return {
    json: {
      page_id: pageId,
      page_name: pageName,
      page_url: pageUrl,

      changed: false,
      is_baseline: false,

      old_hash: oldHash,
      new_hash: newHash,

      old_text: oldText,
      new_text: newText,

      added: [],
      removed: [],

      added_count: 0,
      removed_count: 0,
      changed_count: 0
    }
  };
}

// Normalize text
function normalize(text) {
  return String(text || '')
    .replace(/\s+/g, ' ')
    .trim();
}

const oldWords = normalize(oldText).split(' ').filter(Boolean);
const newWords = normalize(newText).split(' ').filter(Boolean);

// LCS word-level comparison
const m = oldWords.length;
const n = newWords.length;

const dp = Array.from(
  { length: m + 1 },
  () => new Array(n + 1).fill(0)
);

for (let i = m - 1; i >= 0; i--) {
  for (let j = n - 1; j >= 0; j--) {
    if (oldWords[i] === newWords[j]) {
      dp[i][j] = dp[i + 1][j + 1] + 1;
    } else {
      dp[i][j] = Math.max(
        dp[i + 1][j],
        dp[i][j + 1]
      );
    }
  }
}

const added = [];
const removed = [];

let i = 0;
let j = 0;

while (i < m && j < n) {

  if (oldWords[i] === newWords[j]) {
    i++;
    j++;
  }

  else if (dp[i + 1][j] >= dp[i][j + 1]) {
    removed.push(oldWords[i]);
    i++;
  }

  else {
    added.push(newWords[j]);
    j++;
  }
}

while (i < m) {
  removed.push(oldWords[i]);
  i++;
}

while (j < n) {
  added.push(newWords[j]);
  j++;
}

const MAX_ITEMS = 150;

const addedLimited = added.slice(0, MAX_ITEMS);
const removedLimited = removed.slice(0, MAX_ITEMS);

return {
  json: {
    page_id: pageId,
    page_name: pageName,
    page_url: pageUrl,

    changed: true,
    is_baseline: false,

    old_hash: oldHash,
    new_hash: newHash,

    old_text: oldText,
    new_text: newText,

    added: addedLimited,
    removed: removedLimited,

    added_count: added.length,
    removed_count: removed.length,

    changed_count: added.length + removed.length
  }
};

const items = $input.all();

function escapeHtml(value = '') {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

const changedPages = items.filter(
  item => item.json.changed === true
);

if (changedPages.length === 0) {
  return [
    {
      json: {
        subject: 'Page Monitor - No Changes',
        html: `
          <h2>Page Monitor - Daily Check</h2>
          <p>No changes were detected on any monitored page.</p>
          <hr>
          <p style="font-size:12px;color:#666">
            Generated automatically by n8n Page Monitor.
          </p>
        `
      }
    }
  ];
}

let html = `
<h1>Page Changes Detected</h1>

<p>
<strong>${changedPages.length}</strong>
page${changedPages.length === 1 ? '' : 's'} changed.
</p>
`;

for (const item of changedPages) {

  const d = item.json;

  const added = Array.isArray(d.added) ? d.added : [];
  const removed = Array.isArray(d.removed) ? d.removed : [];

  html += `
  <div style="
    margin-bottom:40px;
    padding-bottom:30px;
    border-bottom:1px solid #ccc;
  ">

    <h2>${escapeHtml(d.page_name)}</h2>

    <p>
      <a href="${escapeHtml(d.page_url)}">
        ${escapeHtml(d.page_url)}
      </a>
    </p>
  `;

  if (removed.length > 0) {
    html += `
      <h3 style="color:#c00;">Removed</h3>
      <div style="
        background:#fff1f1;
        padding:12px;
        border-left:4px solid #c00;
        margin-bottom:15px;
      ">
        ${escapeHtml(removed.join(' '))}
      </div>
    `;
  }

  if (added.length > 0) {
    html += `
      <h3 style="color:#080;">Added</h3>
      <div style="
        background:#f1fff1;
        padding:12px;
        border-left:4px solid #080;
        margin-bottom:15px;
      ">
        ${escapeHtml(added.join(' '))}
      </div>
    `;
  }

  html += `
    <p style="font-size:12px;color:#666;">
      ${d.added_count || 0} words added,
      ${d.removed_count || 0} words removed.
    </p>

  </div>
  `;
}

html += `
<hr>
<p style="font-size:12px;color:#666;">
Generated automatically by n8n Page Monitor.
</p>
`;

return [
  {
    json: {
      subject: `Page Update - ${changedPages.length} page${changedPages.length === 1 ? '' : 's'} changed`,
      html: html,
      changed_count: changedPages.length
    }
  }
];
